            engine
                .handle(&original, &clock(101), false)
                .unwrap_err()
                .code,
            "untrusted"
        );
        let mut altered = original.clone();
        if let Request::Confirm {
            prepared_digest, ..
        } = &mut altered
        {
            *prepared_digest = "0".repeat(64);
        }
        assert_eq!(
            engine.handle(&altered, &clock(101), true).unwrap_err().code,
            "stale_confirmation"
        );
