    fn progress_reads_the_tasks_the_watch_looks_at_and_nothing_else() {
        let (mut engine, _) = opened();
        // Prepared, not yet handed over: not watched.
        prepare(&mut engine, 5);
        assert!(engine.watched(&clock(5)).is_empty());
        let id = accepted(&mut engine, 10);
        let revision = engine.revision();
        assert_eq!(
            engine.watched(&clock(70_010)),
            vec![Watched {
                task_id: id,
                machine_id: "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa".into(),
                agent_id: AGENT.into(),
                engine: "codex".into(),
                accepted_ago_ms: Some(70_000),
            }]
        );
        // Listing changes nothing.
        assert_eq!(engine.revision(), revision);
        // In another boot it cannot be dated, and is still watched.
        let other = Clock {
            boot_id: "next-boot".into(),
            monotonic_ms: 1,
        };
        assert_eq!(engine.watched(&other)[0].accepted_ago_ms, None);
        // More than a day old in this boot: left, as the watch leaves it.
        assert!(engine.watched(&clock(11 + WATCH_AT_MOST_MS)).is_empty());
        // Asked for progress without the service holding it: refused, and
        // nothing is changed.
        let asked = engine
            .handle(&Request::GetProgress { id }, &clock(20), false)
            .unwrap_err();
        assert_eq!(asked.code, "progress_off");
        assert_eq!(engine.revision(), revision);
        // Settled: no longer watched.
        let job = request_read(&mut engine, id, 30);
        engine
            .finish_observation(&job, data("Lumi, Sunny and Archie."), &clock(40))
            .unwrap();
        assert!(engine.watched(&clock(50)).is_empty());
    }
    /// #1680: a stored task with a value this build doesn't know, written
    /// with no `schema` bump, never stops the part. It is passed over with a
    /// line, kept in the store as it is (this one is at work on a computer)
    /// and counted; the part serves; and the build that wrote it finds it
    /// again, whole.
    #[test]
    fn a_task_this_build_cannot_read_is_kept_as_it_is_and_the_part_serves() {
        let (mut engine, memory) = opened();
        let at_work = accepted(&mut engine, 0);
        let other = prepare(&mut engine, 0);
        drop(engine);
        let mut later = written(&memory);
        later["tasks"][0]["dispatch"]["state"] = json!("a_state_from_later");
        let unread = later["tasks"][0].clone();
        assert_eq!(unread["id"], at_work);
        let memory = Memory::default();
        memory.0.borrow_mut().bytes = Some(serde_json::to_vec(&later).unwrap());
        let mut engine = Engine::open(memory.clone(), targets(), STORE, RESTART, &clock(1))
            .expect("a task this build can't read does not stop the part");
        assert!(engine.set_aside().is_none(), "nothing is set aside");
        assert_eq!(engine.state.tasks.len(), 1);
        assert_eq!(engine.state.tasks[0].id, other);
        assert_eq!(engine.summary()["unread"], 1);
        assert_eq!(written(&memory)["tasks"][0], unread, "kept as it is");
        // It serves: a new hand-over is prepared and saved, the unread task
        // with it, in order.
        let new = prepare(&mut engine, 2);
        let saved = written(&memory);
        let tasks = saved["tasks"].as_array().unwrap();
        assert_eq!(tasks.len(), 3);
        assert_eq!(tasks[0], unread);
        assert_eq!(tasks[1]["id"], other);
        assert_eq!(tasks[2]["id"], new);
        drop(engine);
        // The build that wrote it, which knows the value, reads it again.
        let mut back = saved;
        back["tasks"][0]["dispatch"]["state"] = json!("accepted");
        let memory = Memory::default();
        memory.0.borrow_mut().bytes = Some(serde_json::to_vec(&back).unwrap());
        let engine = Engine::open(
            memory,
            targets(),
            STORE,
            "44444444444444444444444444444444",
            &clock(3),
        )
        .expect("the newer build reads its task again");
        assert_eq!(engine.state.tasks.len(), 3);
        assert_eq!(engine.state.tasks[0].id, at_work);
        assert_eq!(dispatch(&engine, at_work), DispatchState::Accepted);
        assert_eq!(
            engine.state.tasks[0].dispatch.agent_id.as_deref(),
            Some(AGENT)
        );
    }

    /// Every value a stored enum can hold, by `schema`. A new one can't be
    /// read by the build before it, so it raises [`SCHEMA`] (and
    /// [`State::schema_needed`]) and this line is written again: the
    /// `match`es below stop compiling on a new variant, and the line pins
    /// the vocabulary to the schema (#1680).
    #[test]
    fn a_new_stored_value_comes_with_a_schema_bump() {
        use DispatchState as D;
        use ReadState as R;
        use SpeechState as S;
        fn names<T: Serialize>(kind: &str, all: &[T]) -> String {
            let all: Vec<_> = all
                .iter()
                .map(|value| {
                    serde_json::to_value(value)
                        .unwrap()
                        .as_str()
                        .unwrap()
                        .to_owned()
                })
                .collect();
            format!("{kind}: {}", all.join(" "))
        }
        let dispatch = [
            D::Prepared,
            D::Queued,
            D::Attempting,
            D::Accepted,
            D::Pending,
            D::NotSent,
            D::Uncertain,
            D::Cancelled,
            D::Invalidated,
        ];
        for value in dispatch {
            match value {
                D::Prepared
                | D::Queued
                | D::Attempting
                | D::Accepted
                | D::Pending
                | D::NotSent
                | D::Uncertain
                | D::Cancelled
                | D::Invalidated => {}
            }
        }
        let read = [R::Requested, R::Attempting, R::Finished, R::Failed];
        for value in read {
            match value {
                R::Requested | R::Attempting | R::Finished | R::Failed => {}
            }
        }
        let speech = [S::Claimed, S::Spoken, S::Uncertain];
        for value in speech {
            match value {
                S::Claimed | S::Spoken | S::Uncertain => {}
            }
        }
        let close = [
            CloseState::Attempting,
            CloseState::Closed,
            CloseState::Refused,
            CloseState::Left,
            CloseState::Failed,
        ];
        for value in close {
            match value {
                CloseState::Attempting
                | CloseState::Closed
                | CloseState::Refused
                | CloseState::Left
                | CloseState::Failed => {}
            }
        }
        let engine = [
            EngineKind::Codex,
            EngineKind::Claude,
            EngineKind::Opencode,
            EngineKind::Devin,
            EngineKind::DevinCloud,
        ];
        for value in engine {
            match value {
                EngineKind::Codex
                | EngineKind::Claude
                | EngineKind::Opencode
                | EngineKind::Devin
                | EngineKind::DevinCloud => {}
            }
        }
        let vocabulary = [
            names("dispatch", &dispatch),
            names("read", &read),
            names("speech", &speech),
            names("close", &close),
            names("engine", &engine),
        ]
        .join("; ");
        assert_eq!(
            (SCHEMA, vocabulary.as_str()),
            (
                3,
                "dispatch: prepared queued attempting accepted pending not_sent uncertain cancelled invalidated; \
                 read: requested attempting finished failed; speech: claimed spoken uncertain; \
                 close: attempting closed refused left failed; engine: codex claude opencode devin devin-cloud"
            ),
            "a new stored value needs a `schema` bump (see SCHEMA): raise it, then write this line again"
        );
    }
}

//! Bounded local requests. Trusted Voice attestations use the same envelope,
//! but their authority comes from the runtime route, never a JSON field.
use serde::{Deserialize, Serialize};

pub const MAX_LINE_BYTES: usize = 8192;
pub const MAX_REPLY_BYTES: usize = 131_072;
pub const MAX_PAGE_SIZE: u16 = 8;

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct Guard {
    pub store_id: String,
    pub revision: u64,
    pub request_id: String,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "op", rename_all = "snake_case", deny_unknown_fields)]
pub enum Request {
    Status {},
    /// Who work can be given to: each target's alias and engine, never its
    /// machine or project. The voice tells the model of them.
    Targets {},
    List {
        #[serde(default)]
        after_id: u64,
        #[serde(default = "page_size")]
        limit: u16,
    },
    GetTask {
        id: u64,
    },
    GetObservation {
        id: u64,
        observation_id: u64,
    },
    /// The agent's progress line and what was read with it, kept in memory
    /// with `serve --progress`: for the lamp about to say it.
    GetProgress {
        id: u64,
    },
    Prepare {
        guard: Guard,
        text: String,
        target: String,
    },
    Confirm {
        guard: Guard,
        id: u64,
        prepared_digest: String,
        session_id: String,
    },
    Cancel {
        guard: Guard,
        id: u64,
    },
    Observe {
        guard: Guard,
        id: u64,
    },
    ClaimSpeech {
        guard: Guard,
        id: u64,
        observation_id: u64,
        text: String,
        session_id: String,
    },
    AckSpeech {
        guard: Guard,
        id: u64,
        observation_id: u64,
        claim_id: u64,
        text_digest: String,
        session_id: String,
        played: bool,
    },
    /// The voice told this observation's news (#1390): the model said it in
    /// its own words, so no exact text is claimed. Its harness may then be
    /// closed (`serve --close-told`).
    Told {
        guard: Guard,
        id: u64,
        observation_id: u64,
        session_id: String,
    },
    /// Start Harness's sign-in by a spoken code, or give back the one open
    /// (`serve --sign-in-by-code`, [`crate::sign_in`]): on the trusted
    /// route only, since the code it gives is said aloud by the voice.
    SignInStart {},
    /// Where the sign-in is: its code, the email to ask about, or how it
    /// ended.
    SignInState {},
    /// Atomically take the initial telling of the current code. A new
    /// heard request still uses `SignInStart` to ask for the code again.
    SignInTakeCode {
        id: u64,
    },
    /// The voice heard "Sign in as …?" said whole, for sign-in `id`, in its
    /// `request`: from then an answer is taken.
    SignInAsked {
        id: u64,
        request: u64,
    },
    /// The person's spoken answer to "Sign in as …?", in the voice's
    /// `request`: taken only once it was told, in a later request, within
    /// two minutes ([`crate::sign_in::Session::answer`]).
    SignInAnswer {
        answer: Answer,
        request: u64,
    },
}

/// A spoken yes or no.
#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum Answer {
    Yes,
    No,
}

const fn page_size() -> u16 {
    MAX_PAGE_SIZE
}

impl Request {
    pub fn parse(bytes: &[u8]) -> Result<Self, &'static str> {
        if bytes.len() > MAX_LINE_BYTES {
            return Err("too_long");
        }
        serde_json::from_slice(bytes).map_err(|_| "bad_request")
    }

    pub fn guard(&self) -> Option<&Guard> {
        match self {
            Self::Prepare { guard, .. }
            | Self::Confirm { guard, .. }
            | Self::Cancel { guard, .. }
            | Self::Observe { guard, .. }
            | Self::ClaimSpeech { guard, .. }
            | Self::AckSpeech { guard, .. }
            | Self::Told { guard, .. } => Some(guard),
            _ => None,
        }
    }

    pub fn trusted(&self) -> bool {
        matches!(
            self,
            Self::Confirm { .. }
                | Self::ClaimSpeech { .. }
                | Self::AckSpeech { .. }
                | Self::Told { .. }
                | Self::SignInStart {}
                | Self::SignInState {}
                | Self::SignInTakeCode { .. }
                | Self::SignInAsked { .. }
                | Self::SignInAnswer { .. }
        )
    }

    pub fn session_id(&self) -> Option<&str> {
        match self {
            Self::Confirm { session_id, .. }
            | Self::ClaimSpeech { session_id, .. }
            | Self::AckSpeech { session_id, .. }
            | Self::Told { session_id, .. } => Some(session_id),
            _ => None,
        }
    }

    pub fn name(&self) -> &'static str {
        match self {
            Self::Status {} => "status",
            Self::Targets {} => "targets",
            Self::List { .. } => "list",
            Self::GetTask { .. } => "get_task",
            Self::GetObservation { .. } => "get_observation",
            Self::GetProgress { .. } => "get_progress",
            Self::Prepare { .. } => "prepare",
            Self::Confirm { .. } => "confirm",
            Self::Cancel { .. } => "cancel",
            Self::Observe { .. } => "observe",
            Self::ClaimSpeech { .. } => "claim_speech",
            Self::AckSpeech { .. } => "ack_speech",
            Self::Told { .. } => "told",
            Self::SignInStart {} => "sign_in_start",
            Self::SignInState {} => "sign_in_state",
            Self::SignInTakeCode { .. } => "sign_in_take_code",
            Self::SignInAsked { .. } => "sign_in_asked",
            Self::SignInAnswer { .. } => "sign_in_answer",
        }
    }
}

pub fn refusal(code: &str, message: &str) -> serde_json::Value {
    serde_json::json!({"ok":false,"error":code,"message":message})
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reads_have_no_authority_or_target_override_fields() {
        for bytes in [
            br#"{"op":"status","trusted":true}"#.as_slice(),
            br#"{"op":"get_task","id":1,"machine_id":"other"}"#,
            br#"{"op":"list","limit":1,"engine":"claude"}"#,
            br#"{"op":"targets","engine":"codex"}"#,
            br#"{"op":"get_progress","id":1,"about":"anything"}"#,
            br#"{"op":"get_progress"}"#,
        ] {
            assert_eq!(Request::parse(bytes), Err("bad_request"));
        }
        let targets = Request::parse(br#"{"op":"targets"}"#).unwrap();
        assert_eq!(targets, Request::Targets {});
        assert!(targets.guard().is_none() && !targets.trusted());
        assert_eq!(targets.name(), "targets");
        let progress = Request::parse(br#"{"op":"get_progress","id":3}"#).unwrap();
        assert_eq!(progress, Request::GetProgress { id: 3 });
        assert!(!progress.trusted() && progress.guard().is_none());
        assert_eq!(progress.name(), "get_progress");
        assert_eq!(
            Request::parse(br#"{"op":"list"}"#).unwrap(),
            Request::List {
                after_id: 0,
                limit: MAX_PAGE_SIZE
            }
        );
    }

    #[test]
    fn trusted_operations_require_explicit_fields_and_a_separate_route() {
        let request = Request::parse(br#"{"op":"confirm","guard":{"store_id":"s","revision":0,"request_id":"r"},"id":1,"prepared_digest":"d","session_id":"s"}"#).unwrap();
        assert!(request.trusted());
        assert_eq!(request.session_id(), Some("s"));
        assert_eq!(request.name(), "confirm");
        assert_eq!(
            Request::parse(br#"{"op":"confirm","id":1}"#),
            Err("bad_request")
        );
    }

    /// #1676: the sign-in's operations are the trusted route's; they carry
    /// numbers and a yes or a no, never a code or an email.
    #[test]
    fn sign_in_operations_are_trusted_and_take_only_a_yes_or_a_no() {
        for (bytes, name) in [
            (br#"{"op":"sign_in_start"}"#.as_slice(), "sign_in_start"),
            (br#"{"op":"sign_in_state"}"#, "sign_in_state"),
            (br#"{"op":"sign_in_take_code","id":1}"#, "sign_in_take_code"),
            (
                br#"{"op":"sign_in_asked","id":1,"request":4}"#,
                "sign_in_asked",
            ),
            (
                br#"{"op":"sign_in_answer","answer":"yes","request":5}"#,
                "sign_in_answer",
            ),
        ] {
            let request = Request::parse(bytes).unwrap();
            assert!(request.trusted() && request.guard().is_none(), "{name}");
            assert_eq!(request.name(), name);
        }
        assert_eq!(
            Request::parse(br#"{"op":"sign_in_answer","answer":"no","request":5}"#).unwrap(),
            Request::SignInAnswer {
                answer: Answer::No,
                request: 5
            }
        );
        for bytes in [
            br#"{"op":"sign_in_answer","answer":"maybe","request":5}"#.as_slice(),
            br#"{"op":"sign_in_answer","request":5}"#,
            br#"{"op":"sign_in_answer","answer":"yes"}"#,
            br#"{"op":"sign_in_asked","id":1}"#,
            br#"{"op":"sign_in_asked","id":1,"request":4,"email":"someone@example.com"}"#,
            br#"{"op":"sign_in_start","email":"someone@example.com"}"#,
            br#"{"op":"sign_in_state","code":"12345678"}"#,
            br#"{"op":"sign_in_take_code"}"#,
            br#"{"op":"sign_in_take_code","id":-1}"#,
            br#"{"op":"sign_in_take_code","id":1,"code":"12345678"}"#,
        ] {
            assert_eq!(Request::parse(bytes), Err("bad_request"));
        }
    }

    #[test]
    fn malformed_duplicate_and_oversized_input_is_refused() {
        for bytes in [
            br#"{"op":"status","op":"list"}"#.as_slice(),
            br#"{"op":"get_task","id":-1}"#,
            br#"{"op":"status"}{}"#,
            br#"{"op":"list","limit":65536}"#,
            &[0xff],
        ] {
            assert_eq!(Request::parse(bytes), Err("bad_request"));
        }
        assert_eq!(
            Request::parse(&vec![b' '; MAX_LINE_BYTES + 1]),
            Err("too_long")
        );
    }
}

