/// #560: with `--push-wait`, Harness's own `wait` is held on the agents the
/// watch looks at, and when it comes back the agent is read at once and an
/// idle answer kept without the watch's second look. The injected clock
/// never moves here, so the watch itself never looks: only the push reads.
#[test]
fn a_held_wait_that_comes_back_reads_the_agent_at_once_and_keeps_its_idle_answer() {
    let mut s = Running::unstarted(false, false, true, false);
    s.config.push_wait = true;
    s.start();
    // Nothing handed over: nothing waited on.
    thread::sleep(Duration::from_millis(50));
    assert!(s.counts.waits.lock().unwrap().is_empty());
    let prepared = s.prepare();
    assert_eq!(s.trusted(s.confirmation(&prepared))["ok"], true);
    s.wait(&prepared["id"], |v| {
        v["task"]["dispatch"]["state"] == "accepted"
    });
    // Accepted: one wait, on its agent, and no read yet.
    let start = Instant::now();
    while s.counts.waits.lock().unwrap().is_empty() {
        assert!(start.elapsed() < Duration::from_secs(5), "no wait held");
        thread::sleep(Duration::from_millis(5));
    }
    assert_eq!(
        *s.counts.waits.lock().unwrap(),
        vec![vec![AGENT.to_owned()]]
    );
    thread::sleep(Duration::from_millis(50));
    assert_eq!(s.counts.reads.load(Ordering::SeqCst), 0);
    // The agent ends: read at once, and its idle answer kept on that one
    // read, so the task is settled and the watch lets it go.
    s.counts.idle.store(true, Ordering::SeqCst);
    *s.counts.wait_ends.lock().unwrap() = Some(vec![Ended {
        agent_id: AGENT.into(),
        state: "idle".into(),
    }]);
    let kept = s.wait(&prepared["id"], |v| v["task"]["observations"] == json!(1));
    assert_eq!(s.counts.reads.load(Ordering::SeqCst), 1, "{kept}");
    // Settled: no longer watched, so no wait is held for it again.
    thread::sleep(Duration::from_millis(100));
    assert_eq!(s.counts.waits.lock().unwrap().len(), 1);
    assert_eq!(s.counts.reads.load(Ordering::SeqCst), 1);
}

/// Without `--push-wait` no wait is ever held, whatever the adapter has.
#[test]
fn without_push_wait_no_wait_is_held() {
    let s = Running::configured(false, false, true);
    let prepared = s.prepare();
    assert_eq!(s.trusted(s.confirmation(&prepared))["ok"], true);
    s.wait(&prepared["id"], |v| {
        v["task"]["dispatch"]["state"] == "accepted"
    });
    thread::sleep(Duration::from_millis(100));
    assert!(s.counts.waits.lock().unwrap().is_empty());
}

/// The newest `tasks` diagnostic.
fn tasks_diagnostic(s: &Running) -> Diagnostic {
    let bus = Bus::new(&s.config.bus_root).unwrap();
    let mut diagnostic = bus
        .subscribe_typed(Diagnostic::TOPIC, "tasks_test", Diagnostic::TYPE)
        .unwrap();
    let start = Instant::now();
    loop {
        if let Some(message) = diagnostic.recv(Duration::from_secs(3)).unwrap() {
            let report: Diagnostic = message.parse().unwrap();
            if report.name == "tasks" {
                return report;
            }
        }
        assert!(
            start.elapsed() < Duration::from_secs(5),
            "no tasks diagnostic"
        );
    }
}

/// #1505: task targets written for a newer build (a `version` above this
/// build's, or a field it does not know) keep the part running with
/// hand-overs off. A task offered is refused with why and never reaches
/// Harness, and the part says so every second, where a stopped part would
/// say nothing.
#[test]
fn targets_for_a_newer_build_keep_the_part_running_with_hand_overs_off() {
    let mut s = Running::unstarted(false, false, false, false);
    s.config.targets = BTreeMap::new();
    s.config.targets_newer = Some(2);
    s.start();
    let refused = s.ask(
        json!({"op":"prepare","guard":s.guard(),"text":"Private scripted task","target":"coding"}),
    );
    assert_eq!(refused["ok"], false, "{refused}");
    assert_eq!(refused["error"], "targets_newer", "{refused}");
    assert_eq!(s.status()["summary"]["retained"], 0);
    assert_eq!(s.counts.launches.load(Ordering::SeqCst), 0);
    let report = tasks_diagnostic(&s);
    assert_eq!(report.level, Level::Warn);
    assert_eq!(
        report.message,
        "The task targets were written for a newer build (version 2); hand-overs are off until they match this build"
    );
    assert!(
        report
            .values
            .iter()
            .any(|pair| pair.key == "targets_newer" && pair.value == "2")
    );
}

/// The first `tasks` diagnostic that `wanted` takes, within five seconds.
fn tasks_diagnostic_until(s: &Running, wanted: impl Fn(&Diagnostic) -> bool) -> Diagnostic {
    let start = Instant::now();
    loop {
        let report = tasks_diagnostic(s);
        if wanted(&report) {
            return report;
        }
        assert!(
            start.elapsed() < Duration::from_secs(5),
            "no such tasks diagnostic: {report:?}"
        );
    }
}

fn said(report: &Diagnostic, key: &str) -> Option<String> {
    report
        .values
        .iter()
        .find(|pair| pair.key == key)
        .map(|pair| pair.value.clone())
}

fn write_targets(path: &std::path::Path, bytes: &[u8]) {
    // Written beside and renamed in, as a writer of the real file would.
    let next = path.with_extension("next");
    fs::write(&next, bytes).unwrap();
    fs::set_permissions(&next, fs::Permissions::from_mode(0o600)).unwrap();
    fs::rename(&next, path).unwrap();
}

fn told_targets(s: &Running) -> usize {
    s.ask(json!({"op":"targets"}))["targets"]
        .as_array()
        .unwrap()
        .len()
}

/// #1676: with `serve --set-up-later` the part runs with no targets file,
/// says there is no computer, and uses the file once it is written, with
/// no restart. Harness signed out is said; a file that is not valid keeps
/// the targets before it and is warned of; and a file that is gone leaves
/// no computer again. Not set up is not unwell: the level stays ok.
#[test]
fn set_up_later_reads_the_targets_again_and_says_why_hand_overs_are_off() {
    let mut s = Running::unstarted(false, false, false, false);
    let path = s.root.path().join("targets.json");
    s.config.targets = BTreeMap::new();
    s.config.set_up_later = Some(SetUpLater {
        targets: path.clone(),
        every: Duration::from_millis(50),
        from_machines: None,
    });
    s.start();
    let report = tasks_diagnostic_until(&s, |d| said(d, "handovers_off").is_some());
    assert_eq!(
        said(&report, "handovers_off").as_deref(),
        Some("no_computer")
    );
    assert_eq!(report.level, Level::Ok);
    assert_eq!(
        report.message,
        "No computer to hand tasks to yet: the task targets are missing or empty"
    );
    let refused = s.ask(
        json!({"op":"prepare","guard":s.guard(),"text":"Private scripted task","target":"coding"}),
    );
    assert_eq!(refused["error"], "target", "{refused}");

    let targets = json!({"version":1,"targets":{"coding":{"machine_id":"0123456789abcdef0123456789abcdef","project":"project","engine":"codex"}}});
    write_targets(&path, targets.to_string().as_bytes());
    let start = Instant::now();
    while told_targets(&s) != 1 {
        assert!(
            start.elapsed() < Duration::from_secs(5),
            "targets not read again"
        );
        thread::sleep(Duration::from_millis(10));
    }
    s.prepare();
    let report = tasks_diagnostic_until(&s, |d| said(d, "handovers_off").is_none());
    assert_eq!(said(&report, "signed_in").as_deref(), Some("yes"));

    s.counts.signed_out.store(true, Ordering::SeqCst);
    let report = tasks_diagnostic_until(&s, |d| said(d, "handovers_off").is_some());
    assert_eq!(
        said(&report, "handovers_off").as_deref(),
        Some("not_signed_in")
    );
    assert_eq!(said(&report, "signed_in").as_deref(), Some("no"));
    s.counts.signed_out.store(false, Ordering::SeqCst);

    write_targets(&path, b"{\"version\":1,\"targets\":");
    // File refresh and sign-in observation finish independently. Wait for
    // both before judging the diagnostic; signed-out has higher priority.
    let report = tasks_diagnostic_until(&s, |d| {
        said(d, "targets_invalid").is_some() && said(d, "signed_in").as_deref() == Some("yes")
    });
    assert_eq!(report.level, Level::Warn);
    assert_eq!(
        report.message,
        "The task targets file changed and is not valid; the targets before it are kept"
    );
    assert_eq!(told_targets(&s), 1, "the targets before are kept");

    fs::remove_file(&path).unwrap();
    let report = tasks_diagnostic_until(&s, |d| {
        said(d, "handovers_off").as_deref() == Some("no_computer")
    });
    assert!(said(&report, "targets_invalid").is_none());
    assert_eq!(told_targets(&s), 0);
}

/// #1676: with `--targets-from-machines`, a lamp signed in to Harness writes
/// its targets from the person's machines and uses them with no restart: the
/// first is `office`, the voice's own default. A machine added is added; the
/// machines are not asked while signed out.
#[test]
fn targets_from_machines_are_written_and_used_while_signed_in() {
    let mut s = Running::unstarted(false, false, false, false);
    let path = s.root.path().join("targets.json");
    s.config.targets = BTreeMap::new();
    // A look every 20 ms, the machines' every 100 (#1806).
    s.config.set_up_later = Some(SetUpLater {
        targets: path.clone(),
        every: Duration::from_millis(20),
        from_machines: Some(EngineKind::Claude),
    });
    let machine = |id: char, label: &str, current: bool| AccountMachine {
        machine_id: id.to_string().repeat(32),
        label: label.into(),
        current,
    };
    *s.counts.machines.lock().unwrap() = vec![
        machine('a', "lamp", true),
        machine('b', "Office iMac", false),
    ];
    s.start();
    let until = |count: usize| {
        let start = Instant::now();
        while told_targets(&s) != count {
            assert!(
                start.elapsed() < Duration::from_secs(5),
                "not {count} targets"
            );
            thread::sleep(Duration::from_millis(10));
        }
    };
    until(1);
    // With its own name beside it (#1676).
    let start = Instant::now();
    while s.ask(json!({"op":"targets"}))["targets"]
        != json!([{"alias":"office","engine":"claude","name":"Office iMac"}])
    {
        assert!(start.elapsed() < Duration::from_secs(5), "no name told");
        thread::sleep(Duration::from_millis(10));
    }
    let report = tasks_diagnostic_until(&s, |d| said(d, "handovers_off").is_none());
    assert_eq!(said(&report, "signed_in").as_deref(), Some("yes"));

    s.counts.signed_out.store(true, Ordering::SeqCst);
    tasks_diagnostic_until(&s, |d| said(d, "signed_in").as_deref() == Some("no"));
    let asked = s.counts.machine_reads.load(Ordering::SeqCst);
    s.counts
        .machines
        .lock()
        .unwrap()
        .push(machine('c', "MacBook Air", false));
    // Keep the original 600 ms observation: sign-in calls are not the
    // machines timer, and a call can be counted before its result is used.
    let unchanged = || {
        assert_eq!(
            s.counts.machine_reads.load(Ordering::SeqCst),
            asked,
            "asked while signed out"
        );
    };
    let start = Instant::now();
    let report = tasks_diagnostic_until(&s, |_| {
        unchanged();
        start.elapsed() >= Duration::from_millis(600)
    });
    let requests: u64 = said(&report, "requests").unwrap().parse().unwrap();
    let answer = s.ask(json!({"op":"targets"}));
    assert_eq!(answer["ok"], true, "{answer}");
    // The owner reports this request only after scheduling jobs. Two more
    // sign-in reads after it mean whole passes ran past it while signed out,
    // each choosing the machines or not, rather than just that the request
    // was answered. Not an idle report: the sign-in is asked every 20 ms
    // here, so on a slow runner the worker is busy at nearly every report
    // (lamp-voice's ARM64 at 07:58 and #2936's at 15:44, 22 Oct).
    let reads = s.counts.sign_in_reads.load(Ordering::SeqCst);
    tasks_diagnostic_until(&s, |d| {
        unchanged();
        said(d, "requests")
            .and_then(|count| count.parse::<u64>().ok())
            .is_some_and(|count| count > requests)
            && said(d, "signed_in").as_deref() == Some("no")
            && s.counts.sign_in_reads.load(Ordering::SeqCst) >= reads + 2
    });
    assert_eq!(
        s.counts.machine_reads.load(Ordering::SeqCst),
        asked,
        "asked while signed out"
    );
    assert_eq!(told_targets(&s), 1);

    s.counts.signed_out.store(false, Ordering::SeqCst);
    until(2);
    let told = s.ask(json!({"op":"targets"}));
    let start = Instant::now();
    while s.ask(json!({"op":"targets"}))["targets"]
        != json!([{"alias":"macbook-air","engine":"claude","name":"MacBook Air"},
            {"alias":"office","engine":"claude","name":"Office iMac"}])
    {
        assert!(start.elapsed() < Duration::from_secs(5), "{told}");
        thread::sleep(Duration::from_millis(10));
    }
    // The first renamed: the same alias, its new name told.
    s.counts.machines.lock().unwrap()[1].label = "Studio".into();
    let start = Instant::now();
    while s.ask(json!({"op":"targets"}))["targets"][1]["name"] != "Studio" {
        assert!(start.elapsed() < Duration::from_secs(5), "rename not told");
        thread::sleep(Duration::from_millis(10));
    }
    assert_eq!(
        s.ask(json!({"op":"targets"}))["targets"][1]["alias"],
        "office"
    );
}

#[test]
fn sign_in_code_claims_share_one_owner_and_keep_legacy_repeats_explicit() {
    use lamp_tasks::sign_in::Event;
    let off = Running::new(false);
    assert_eq!(
        off.trusted(json!({"op":"sign_in_take_code","id":1}))["error"],
        "sign_in_off"
    );
    let mut s = Running::unstarted(false, false, false, false);
    s.config.sign_in_by_code = true;
    s.start();
    let state = s.trusted(json!({"op":"sign_in_state"}));
    assert_eq!(state["sign_in"], "none");
    assert_eq!(state["code_claims"], 1);
    let absent = s.trusted(json!({"op":"sign_in_take_code","id":1}));
    assert_eq!(absent["claim"], "not_available");
    assert!(absent.get("code").is_none());
    assert_eq!(s.counts.sign_in_starts.load(Ordering::SeqCst), 0);

    let started = s.trusted(json!({"op":"sign_in_start"}));
    assert_eq!(started["sign_in"], "starting");
    let id = started["id"].as_u64().unwrap();
    assert_eq!(
        s.trusted(json!({"op":"sign_in_take_code","id":id}))["claim"],
        "waiting"
    );
    s.counts
        .sign_in_lines
        .lock()
        .unwrap()
        .push_back(Ok(Event::Code {
            code: "12345678".into(),
            expires_in: 120,
        }));
    let untrusted = s.ask(json!({"op":"sign_in_take_code","id":id}));
    assert_eq!(untrusted["error"], "untrusted");
    assert!(untrusted.get("code").is_none());
    let stale = s.trusted(json!({"op":"sign_in_take_code","id":id + 1}));
    assert_eq!(stale["claim"], "not_available");
    assert!(stale.get("code").is_none());

    // Whichever Voice process claims first owns this initial payload.
    let first = s.trusted(json!({"op":"sign_in_take_code","id":id}));
    assert_eq!(first["claim"], "granted");
    assert_eq!(first["sign_in"], "code");
    assert_eq!(first["code"], "12345678");
    assert_eq!(first["code_told"], true);
    let second = s.trusted(json!({"op":"sign_in_take_code","id":id}));
    assert_eq!(second["claim"], "already_given");
    assert!(second.get("code").is_none());
    assert!(second.get("email").is_none());
    let repeated = s.trusted(json!({"op":"sign_in_start"}));
    assert_eq!(repeated["id"], id);
    assert_eq!(repeated["code"], "12345678");
    assert_eq!(repeated["code_told"], true);
    s.counts
        .sign_in_lines
        .lock()
        .unwrap()
        .push_back(Ok(Event::Code {
            code: "12345678".into(),
            expires_in: 120,
        }));
    let kept = s.trusted(json!({"op":"sign_in_take_code","id":id}));
    assert_eq!(kept["claim"], "already_given");
    assert!(kept.get("code").is_none());

    // The opposite order: a legacy START reply consumes the next code's
    // initial handoff before a news reader tries its claim.
    s.counts
        .sign_in_lines
        .lock()
        .unwrap()
        .push_back(Ok(Event::Code {
            code: "87654321".into(),
            expires_in: 120,
        }));
    let legacy = s.trusted(json!({"op":"sign_in_start"}));
    assert_eq!(legacy["code"], "87654321");
    assert_eq!(legacy["code_told"], true);
    let after_legacy = s.trusted(json!({"op":"sign_in_take_code","id":id}));
    assert_eq!(after_legacy["claim"], "already_given");
    assert!(after_legacy.get("code").is_none());
    assert_eq!(s.counts.sign_in_starts.load(Ordering::SeqCst), 1);
    assert!(s.counts.sign_in_answers.lock().unwrap().is_empty());
}

/// #1676: Harness's sign-in by a spoken code through the service, on the
/// trusted route only: started once while open, its code, the question,
/// the answer passed on only once the voice heard the question told, in a
/// later request, and how it ended, kept for the voice; started anew, with
/// the next id, once done. Without `--sign-in-by-code` it is off.
#[test]
fn the_sign_in_by_code_is_the_trusted_routes_from_its_code_to_its_end() {
    use lamp_tasks::sign_in::{Done, Event};
    let off = Running::new(false);
    assert_eq!(
        off.trusted(json!({"op":"sign_in_start"}))["error"],
        "sign_in_off"
    );
    let mut s = Running::unstarted(false, false, false, false);
    s.config.sign_in_by_code = true;
    s.start();
    assert_eq!(s.ask(json!({"op":"sign_in_start"}))["error"], "untrusted");
    assert_eq!(s.ask(json!({"op":"sign_in_state"}))["error"], "untrusted");
    assert_eq!(s.trusted(json!({"op":"sign_in_state"}))["sign_in"], "none");
    s.counts
        .sign_in_lines
        .lock()
        .unwrap()
        .push_back(Ok(Event::Code {
            code: "12345678".into(),
            expires_in: 120,
        }));
    let started = s.trusted(json!({"op":"sign_in_start"}));
    assert_eq!(started["ok"], true, "{started}");
    assert_eq!(started["sign_in"], "code");
    assert_eq!(started["code"], "12345678");
    // Counted from the clock, so not taken for one before a restart.
    let id = started["id"].as_u64().unwrap();
    assert!(id > 1_700_000_000_000, "{started}");
    assert_eq!(started["code_told"], true);
    // Asked again while open: the same one, not another.
    assert_eq!(s.trusted(json!({"op":"sign_in_start"}))["code"], "12345678");
    assert_eq!(s.counts.sign_in_starts.load(Ordering::SeqCst), 1);
    assert_eq!(
        s.trusted(json!({"op":"sign_in_answer","answer":"yes","request":2}))["error"],
        "not_asking"
    );
    assert_eq!(
        s.trusted(json!({"op":"sign_in_asked","id":id,"request":2}))["error"],
        "not_asking"
    );
    s.counts
        .sign_in_lines
        .lock()
        .unwrap()
        .push_back(Ok(Event::Confirm {
            email: "someone@example.com".into(),
        }));
    let until = |want: &str| {
        let start = Instant::now();
        loop {
            let state = s.trusted(json!({"op":"sign_in_state"}));
            if state["sign_in"] == want {
                return state;
            }
            assert!(start.elapsed() < Duration::from_secs(5), "{state}");
            thread::sleep(Duration::from_millis(10));
        }
    };
    assert_eq!(until("asking")["email"], "someone@example.com");
    assert_eq!(
        s.ask(json!({"op":"sign_in_answer","answer":"yes","request":9}))["error"],
        "untrusted"
    );
    assert_eq!(
        s.ask(json!({"op":"sign_in_asked","id":id,"request":3}))["error"],
        "untrusted"
    );
    // Asked in Harness, but not yet heard said by the lamp: a yes is for
    // something else.
    assert_eq!(
        s.trusted(json!({"op":"sign_in_answer","answer":"yes","request":9}))["error"],
        "not_told"
    );
    assert_eq!(
        s.trusted(json!({"op":"sign_in_asked","id":id + 7,"request":3}))["error"],
        "not_this_sign_in"
    );
    let told = s.trusted(json!({"op":"sign_in_asked","id":id,"request":3}));
    assert_eq!(told["sign_in"], "asking", "{told}");
    // The yes in the request the question was told in isn't its answer.
    assert_eq!(
        s.trusted(json!({"op":"sign_in_answer","answer":"yes","request":3}))["error"],
        "not_told"
    );
    assert!(s.counts.sign_in_answers.lock().unwrap().is_empty());
    let answered = s.trusted(json!({"op":"sign_in_answer","answer":"yes","request":4}));
    assert_eq!(answered["sign_in"], "answered", "{answered}");
    assert_eq!(*s.counts.sign_in_answers.lock().unwrap(), [true]);
    s.counts
        .sign_in_lines
        .lock()
        .unwrap()
        .push_back(Ok(Event::Result(Done::Success {
            email: Some("someone@example.com".into()),
        })));
    // Not before the sign-in has succeeded.
    assert_eq!(s.counts.daemon_starts.load(Ordering::SeqCst), 0);
    assert_eq!(until("done")["result"], "success");
    // Harness's own sign-in stops its daemon (openharness#1463): started
    // once after it, and not again.
    let start = Instant::now();
    while s.counts.daemon_starts.load(Ordering::SeqCst) == 0 {
        assert!(
            start.elapsed() < Duration::from_secs(5),
            "the daemon was never started"
        );
        thread::sleep(Duration::from_millis(10));
    }
    thread::sleep(Duration::from_millis(200));
    assert_eq!(s.counts.daemon_starts.load(Ordering::SeqCst), 1);
    // Done: kept for the voice, and a start begins anew.
    assert_eq!(
        s.trusted(json!({"op":"sign_in_state"}))["result"],
        "success"
    );
    assert_eq!(s.trusted(json!({"op":"sign_in_start"}))["id"], id + 1);
    assert_eq!(s.counts.sign_in_starts.load(Ordering::SeqCst), 2);
}

/// openharness#1463, the reviewer-lead's P2 on #2309: a hand-over waiting
/// when a sign-in by code succeeds goes to Harness only after its daemon
/// was started again, and a sign-in that fails starts nothing (the
/// reviewer's P3 2).
#[test]
fn after_a_sign_in_the_daemon_is_started_before_a_waiting_hand_over() {
    use lamp_tasks::sign_in::{Done, Event};
    let mut s = Running::new(false);
    s.stop();
    s.config.sign_in_by_code = true;
    s.start();
    let state = |s: &Running, want: &str| {
        let start = Instant::now();
        loop {
            let state = s.trusted(json!({"op":"sign_in_state"}));
            if state["sign_in"] == want {
                return state;
            }
            assert!(start.elapsed() < Duration::from_secs(5), "{state}");
            thread::sleep(Duration::from_millis(10));
        }
    };
    // Refused or cancelled: nothing is started. Each ends after its start,
    // so the loop sees it open first (the reviewer's P3 on #2309).
    for code in ["DENIED", "CANCELLED"] {
        s.counts
            .sign_in_lines
            .lock()
            .unwrap()
            .push_back(Ok(Event::Code {
                code: "12345678".into(),
                expires_in: 120,
            }));
        let started = s.trusted(json!({"op":"sign_in_start"}));
        assert_eq!(started["ok"], true, "{started}");
        state(&s, "code");
        s.counts
            .sign_in_lines
            .lock()
            .unwrap()
            .push_back(Ok(Event::Result(Done::Error { code: code.into() })));
        let ended = state(&s, "done");
        assert_eq!(ended["result"], "error", "{ended}");
    }
    thread::sleep(Duration::from_millis(200));
    assert_eq!(s.counts.daemon_starts.load(Ordering::SeqCst), 0);
    // A first hand-over holds the job lane while the sign-in succeeds and
    // a second is confirmed.
    s.counts.hold_launch.store(true, Ordering::SeqCst);
    let first = s.prepare();
    assert_eq!(s.trusted(s.confirmation(&first))["ok"], true);
    let start = Instant::now();
    while s.counts.launches.load(Ordering::SeqCst) == 0 {
        assert!(start.elapsed() < Duration::from_secs(5));
        thread::sleep(Duration::from_millis(5));
    }
    assert_eq!(s.trusted(json!({"op":"sign_in_start"}))["ok"], true);
    s.counts
        .sign_in_lines
        .lock()
        .unwrap()
        .push_back(Ok(Event::Result(Done::Success { email: None })));
    assert_eq!(state(&s, "done")["result"], "success");
    let second = s.prepare();
    assert_eq!(s.trusted(s.confirmation(&second))["ok"], true);
    thread::sleep(Duration::from_millis(100));
    s.counts.hold_launch.store(false, Ordering::SeqCst);
    let start = Instant::now();
    while s.counts.launches.load(Ordering::SeqCst) < 2 {
        assert!(
            start.elapsed() < Duration::from_secs(5),
            "{:?}",
            s.counts.order
        );
        thread::sleep(Duration::from_millis(5));
    }
    assert_eq!(
        *s.counts.order.lock().unwrap(),
        ["launch", "daemon", "launch"]
    );
    // Each launch's end kept before the service is stopped: the store syncs
    // with `fullfsync`, and on a Mac under the whole binary's load a write
    // still under way took past the stop's 300 ms (#1569 row 76).
    for prepared in [&first, &second] {
        s.wait(&prepared["id"], |v| {
            !v["task"]["dispatch"]["finished"].is_null()
        });
    }
}

/// lamp-75c9, 21 October: the daemon's start right after a spoken sign-in
/// said `start_failed`, and one by hand a minute later worked. A failed
/// start is tried again later, twice as long after each failure, and a
/// hand-over confirmed meanwhile waits for it; after the last try it goes
/// as before.
#[test]
fn a_failed_daemon_start_is_tried_again_before_a_waiting_hand_over() {
    use lamp_tasks::sign_in::{Done, Event};
    let mut s = Running::new(false);
    s.stop();
    s.config.sign_in_by_code = true;
    s.start();
    let signed_in = |s: &Running| {
        assert_eq!(s.trusted(json!({"op":"sign_in_start"}))["ok"], true);
        s.counts
            .sign_in_lines
            .lock()
            .unwrap()
            .push_back(Ok(Event::Result(Done::Success { email: None })));
    };
    let launched = |s: &Running, want: usize| {
        let start = Instant::now();
        while s.counts.launches.load(Ordering::SeqCst) < want {
            assert!(
                start.elapsed() < Duration::from_secs(5),
                "{:?}",
                s.counts.order
            );
            thread::sleep(Duration::from_millis(5));
        }
    };
    // Two starts fail: the third, 50 and 100 ms later, works, and the
    // hand-over confirmed after the first failure goes only then.
    s.counts.daemon_fails.store(2, Ordering::SeqCst);
    signed_in(&s);
    let start = Instant::now();
    while s.counts.daemon_starts.load(Ordering::SeqCst) == 0 {
        assert!(start.elapsed() < Duration::from_secs(5), "never started");
        thread::sleep(Duration::from_millis(2));
    }
    let first = s.prepare();
    assert_eq!(s.trusted(s.confirmation(&first))["ok"], true);
    launched(&s, 1);
    assert_eq!(
        *s.counts.order.lock().unwrap(),
        ["daemon", "daemon", "daemon", "launch"]
    );
    // Every try fails: four in all, and then the hand-over goes as before.
    s.counts.order.lock().unwrap().clear();
    s.counts.daemon_fails.store(10, Ordering::SeqCst);
    signed_in(&s);
    let start = Instant::now();
    while s.counts.daemon_starts.load(Ordering::SeqCst) < 4 {
        assert!(start.elapsed() < Duration::from_secs(5), "not tried again");
        thread::sleep(Duration::from_millis(2));
    }
    let second = s.prepare();
    assert_eq!(s.trusted(s.confirmation(&second))["ok"], true);
    launched(&s, 2);
    thread::sleep(Duration::from_millis(500));
    assert_eq!(
        *s.counts.order.lock().unwrap(),
        ["daemon", "daemon", "daemon", "daemon", "launch"]
    );
    // Each launch's end kept before the service is stopped: the store syncs
    // with `fullfsync`, and on a Mac under the whole binary's load a write
    // still under way took past the stop's 300 ms (#1569 row 76).
    for prepared in [&first, &second] {
        s.wait(&prepared["id"], |v| {
            !v["task"]["dispatch"]["finished"].is_null()
        });
    }
}

/// Without `serve --set-up-later` nothing of it is said, and the targets
/// file is not looked at again.
#[test]
fn without_set_up_later_the_report_is_as_before() {
    let s = Running::new(false);
    s.counts.signed_out.store(true, Ordering::SeqCst);
    thread::sleep(Duration::from_millis(100));
    let report = tasks_diagnostic(&s);
    for key in ["handovers_off", "signed_in", "targets_invalid"] {
        assert!(said(&report, key).is_none(), "{key}: {report:?}");
    }
    assert_eq!(report.message, "");
    assert_eq!(told_targets(&s), 1);
}

/// The store once the stopped service's owner has let its folder go. A
/// start once failed here with "tasks directory is already owned" (once in
/// twelve full runs of this file): a child another test spawned held a copy
/// of the lock ([`SPAWNS`]). The store is let go in the turn's share too.
fn released(s: &Running) -> Released {
    let share = share();
    let start = Instant::now();
    loop {
        match Store::open(&s.config.dir) {
            Ok(store) => {
                return Released {
                    store,
                    _share: share,
                };
            }
            Err(error) if error.kind() == io::ErrorKind::WouldBlock => {
                assert!(
                    start.elapsed() < Duration::from_secs(5),
                    "the store stayed owned"
                );
                thread::sleep(Duration::from_millis(5));
            }
            Err(error) => panic!("{error}"),
        }
    }
}

/// A store the test opened itself, let go before its share of the turn.
struct Released {
    store: Store,
    _share: RwLockReadGuard<'static, ()>,
}

impl std::ops::Deref for Released {
    type Target = Store;
    fn deref(&self) -> &Store {
        &self.store
    }
}

impl std::ops::DerefMut for Released {
    fn deref_mut(&mut self) -> &mut Store {
        &mut self.store
    }
}

/// #1505: a store a newer build wrote is set aside, and until someone looks
/// (the kept file removed, or put back by hand), the part says so: across a
/// restart too, and not once it is gone.
#[test]
fn a_store_set_aside_is_said_until_its_file_is_gone() {
    let mut s = Running::new(false);
    s.stop();
    let mut store = released(&s);
    let mut newer: Value = serde_json::from_slice(&store.load().unwrap().unwrap()).unwrap();
    newer["schema"] = json!(4);
    store.commit(&serde_json::to_vec(&newer).unwrap()).unwrap();
    drop(store);
    s.start();
    let said = |s: &Running| {
        let report = tasks_diagnostic(s);
        let kept = report
            .values
            .iter()
            .find(|pair| pair.key == "set_aside")
            .map(|pair| pair.value.clone());
        (report.level, report.message, kept)
    };
    let (level, message, kept) = said(&s);
    assert_eq!(level, Level::Warn);
    assert_eq!(
        message,
        "Tasks set aside a store from a newer build; its tasks are not followed"
    );
    let kept = kept.expect("the kept file is named");
    assert!(kept.starts_with("tasks.sqlite3.newer-4-"), "{kept}");
    // Restarted: the store opens well now, and the kept file is still said.
    s.stop();
    drop(released(&s));
    s.start();
    assert_eq!(said(&s).2.as_deref(), Some(kept.as_str()));
    // Someone looked: the file is gone, and it is said no more.
    s.stop();
    drop(released(&s));
    std::fs::remove_file(s.config.dir.join(&kept)).unwrap();
    s.start();
    let (level, message, kept) = said(&s);
    assert_eq!((level, message.as_str(), kept), (Level::Ok, "", None));
}

/// #1676: `--targets-from-machines` takes an engine Harness knows, and only
/// goes with `--set-up-later`, refused before anything is read.
#[test]
fn targets_from_machines_needs_an_engine_and_set_up_later() {
    let refused = |args: &[&str]| {
        let output = output_of(Command::new(env!("CARGO_BIN_EXE_lamp-tasks")).args(args));
        assert!(!output.status.success(), "{args:?}");
        String::from_utf8_lossy(&output.stderr).into_owned()
    };
    let base = [
        "serve",
        "--enable",
        "--targets",
        "/does-not-exist",
        "--harness",
        "/does-not-exist",
    ];
    let without = refused(&[&base[..], &["--targets-from-machines", "claude"]].concat());
    assert!(without.contains("only with --set-up-later"), "{without}");
    let unknown = refused(
        &[
            &base[..],
            &["--set-up-later", "--targets-from-machines", "gpt"],
        ]
        .concat(),
    );
    assert!(
        unknown.contains("needs claude, codex or opencode"),
        "{unknown}"
    );
}

/// The tasks database, opened by hand as a newer build would write it.
fn tasks_database(s: &Running) -> rusqlite::Connection {
    rusqlite::Connection::open(s.config.dir.join("tasks.sqlite3")).unwrap()
}

/// #1680: a tasks database from a newer build (`user_version` 2) doesn't
/// stop the part: it is kept whole, the part starts with an empty store,
/// serves, and says so on health.
#[test]
fn a_newer_tasks_database_is_set_aside_and_the_part_serves() {
    let mut s = Running::new(false);
    let prepared = s.prepare();
    s.stop();
    tasks_database(&s)
        .execute_batch("PRAGMA user_version=2")
        .unwrap();
    s.start();
    assert_eq!(s.status()["summary"]["retained"], 0);
    let kept = s.status()["summary"]["set_aside"]
        .as_str()
        .expect("the kept store is said")
        .to_owned();
    assert!(kept.starts_with("tasks.sqlite3.newer-db2-"), "{kept}");
    let old = rusqlite::Connection::open(s.config.dir.join(&kept)).unwrap();
    let snapshot: Vec<u8> = old
        .query_row("SELECT snapshot FROM state", [], |row| row.get(0))
        .unwrap();
    let snapshot: Value = serde_json::from_slice(&snapshot).unwrap();
    assert_eq!(
        snapshot["tasks"][0]["id"], prepared["id"],
        "its task is kept"
    );
    drop(old);
    s.prepare();
    let report = tasks_diagnostic_until(&s, |report| {
        report.values.iter().any(|pair| pair.key == "set_aside")
    });
    assert_eq!(report.level, Level::Warn);
}

/// #1680: a stored task with a value this build doesn't know, at the same
/// `schema`, doesn't stop the part: it is kept in the store as it is, the
/// part serves, and health counts it.
#[test]
fn a_stored_task_this_build_cannot_read_is_kept_and_the_part_serves() {
    let mut s = Running::new(false);
    let prepared = s.prepare();
    s.stop();
    let db = tasks_database(&s);
    let snapshot: Vec<u8> = db
        .query_row("SELECT snapshot FROM state", [], |row| row.get(0))
        .unwrap();
    let mut state: Value = serde_json::from_slice(&snapshot).unwrap();
    state["tasks"][0]["dispatch"]["state"] = json!("a_state_from_later");
    let later = state["tasks"][0].clone();
    db.execute(
        "UPDATE state SET snapshot = ?1",
        [serde_json::to_vec(&state).unwrap()],
    )
    .unwrap();
    drop(db);
    s.start();
    let summary = s.status()["summary"].clone();
    assert_eq!(summary["retained"], 0, "{summary}");
    assert_eq!(summary["unread"], 1, "{summary}");
    assert!(summary["set_aside"].is_null(), "{summary}");
    let next = s.prepare();
    assert_ne!(next["id"], prepared["id"]);
    let report = tasks_diagnostic_until(&s, |report| {
        report
            .values
            .iter()
            .any(|pair| pair.key == "unread" && pair.value == "1")
    });
    assert_eq!(report.level, Level::Warn);
    s.stop();
    let snapshot: Vec<u8> = tasks_database(&s)
        .query_row("SELECT snapshot FROM state", [], |row| row.get(0))
        .unwrap();
    let state: Value = serde_json::from_slice(&snapshot).unwrap();
    assert_eq!(state["tasks"][0], later, "kept as it is");
    assert_eq!(state["tasks"][1]["id"], next["id"]);
}

//! Signing the lamp's Harness in by voice (#1676, `LAMP_TASKS_SIGN_IN=on`,
//! [`crate::agent_tasks::SIGN_IN_FLAG`]). A lamp has no screen for Harness's
//! QR code; Harness 0.4.23 signs a device in by a code it says aloud
//! (openharness#1410). The tasks part runs Harness's own sign-in and passes
//! the answer on (`lamp-tasks serve --sign-in-by-code`, its trusted ops
//! `sign_in_start`, `sign_in_state`, `sign_in_take_code`, `sign_in_asked`
//! and `sign_in_answer`).
//! Where the sign-in is, whether its question was heard and whether an
//! answer may be taken are kept there only: the voice's news runs in its
//! coordinator and its tools in a worker, two processes. The voice:
//!
//! - **starts it** when the person asks ([`START`]), and says the code's
//!   digits and where to type them: Harness on their computer, or its site;
//! - **asks** "Sign in as …?" unasked once they have approved in Harness,
//!   the email read back slowly ("dot", "at"), as news
//!   ([`crate::task_news`], [`news`]); a code that came after the call
//!   answered is told the same way;
//! - **says the question was heard** ([`tell_asked`]) once its news turn was
//!   heard whole, with that turn's request;
//! - **passes on their answer** ([`ANSWER`]), only one spoken to the lamp,
//!   in a later request, as the tasks part allows;
//! - **says how it went**, again as news.
//!
//! No session exists before the person's yes, so a stranger who heard the
//! code gains nothing. Only a request the lamp heard may start a sign-in or
//! answer it, never one it wrote, a reminder or a text.
use lamp_gemini::{Tool, ToolCall};
use serde_json::{Value, json};
use std::{
    collections::BTreeSet,
    path::{Path, PathBuf},
    sync::Mutex,
    time::{Duration, Instant},
};

pub const START: &str = "sign_in_computer";
pub const ANSWER: &str = "sign_in_answer";
/// How long [`START`] waits for Harness's first code within its deadline:
/// a code that comes later is told as news.
const LOOK_EVERY: Duration = Duration::from_millis(200);
/// What the voice asks the tasks part by, connecting included.
const ASK_DEADLINE: Duration = Duration::from_millis(1_000);

/// How often the news reads a sign-in while one is open: the question
/// comes soon after the person approves in Harness (the reviewer's P3).
pub const READ_OPEN_EVERY: Duration = Duration::from_secs(2);

/// A sign-in's question taken to be told but not heard whole is offered
/// again this long after it was taken, while the tasks part still says
/// `asking` (the 21 Oct lamp-75c9 rerun's (3), #2602): on lamp-75c9 talk
/// in the room cut it short a second after it began, it was kept as told,
/// and the person's yes was refused as `not_told` from then on. Past a
/// question's own turn and its tail, so one being told isn't told twice.
pub const ASK_AGAIN_AFTER: Duration = Duration::from_secs(30);

/// How many times in all a sign-in's question is taken to be told: once,
/// and twice again if it isn't heard whole. Harness gives the person a few
/// minutes to answer, and a room this busy is let be after that.
pub const ASKED_MOST: u32 = 3;

/// Each sign-in's question taken to be told, by id: when it was last taken
/// (`None` once offered again) and how many times ([`ASK_AGAIN_AFTER`]).
#[derive(Debug, Default)]
pub struct AskAgain {
    told: std::collections::BTreeMap<u64, (Option<Instant>, u32)>,
}

impl AskAgain {
    /// The news `key` was taken to be told at `now`. Whether it is a
    /// sign-in's question, followed here rather than kept as told.
    pub fn told(&mut self, key: &str, now: Instant) -> bool {
        let Some(id) = asked_of(key) else {
            return false;
        };
        let (at, times) = self.told.entry(id).or_insert((None, 0));
        *at = Some(now);
        *times += 1;
        true
    }

    /// The questions followed here that were heard whole since (`heard`,
    /// the sign-ins whose question was): let go, to be kept as told, so a
    /// restart doesn't say them again (the reviewer-lead's P3 1 on #2702).
    pub fn heard(&mut self, heard: &std::collections::BTreeSet<u64>) -> Vec<String> {
        let ids: Vec<u64> = self
            .told
            .keys()
            .filter(|id| heard.contains(id))
            .copied()
            .collect();
        ids.into_iter()
            .map(|id| {
                self.told.remove(&id);
                key(id, "asking")
            })
            .collect()
    }

    /// The questions to offer again at `now`: taken to be told `after` ago
    /// or more, not heard whole (call [`Self::heard`] first), and taken
    /// fewer than [`ASKED_MOST`] times. Each is given once a telling. One
    /// told the last time is let go once its wait has passed (the
    /// reviewer-lead's P3 2 on #2702): it is in `offered` and never
    /// offered again.
    pub fn due(&mut self, after: Duration, now: Instant) -> Vec<String> {
        let waited =
            |at: &Option<Instant>| at.is_some_and(|at| now.saturating_duration_since(at) >= after);
        self.told
            .retain(|_, (at, times)| *times < ASKED_MOST || !waited(at));
        let mut due = Vec::new();
        for (id, (at, _)) in &mut self.told {
            if waited(at) {
                *at = None;
                due.push(key(*id, "asking"));
            }
        }
        due
    }

    /// How many questions are followed: for a test.
    #[cfg(test)]
    fn followed(&self) -> usize {
        self.told.len()
    }
}

/// The newest sign-in's code and email, never kept anywhere but here: what
/// [`scrub`] takes out of what the thread keeps. Kept until `until`, then
/// forgotten (the reviewer's P3 5 on #2137).
#[derive(Default)]
struct Said {
    code: Option<String>,
    email: Option<String>,
    until: Option<Instant>,
}
static SAID: Mutex<Said> = Mutex::new(Said {
    code: None,
    email: None,
    until: None,
});

/// How long the code and the account are kept after the newest news of
/// them, at most: a sign-in lasts a few minutes.
const KEPT_OPEN: Duration = Duration::from_secs(15 * 60);
/// How long they are kept once the sign-in ended: the person may still
/// say them back.
const KEPT_AFTER: Duration = Duration::from_secs(120);

fn keep_said(code: Option<&str>, email: Option<&str>) {
    if let Ok(mut said) = SAID.lock() {
        if let Some(code) = code {
            said.code = Some(code.to_owned());
        }
        if let Some(email) = email {
            said.email = Some(email.to_owned());
        }
        if said.code.is_some() || said.email.is_some() {
            said.until = Some(Instant::now() + KEPT_OPEN);
        }
    }
}

/// The sign-in ended: its code and account are kept [`KEPT_AFTER`] more.
fn said_ended() {
    if let Ok(mut said) = SAID.lock()
        && (said.code.is_some() || said.email.is_some())
    {
        said.until = Some(Instant::now() + KEPT_AFTER);
    }
}

/// `said`, forgotten once its time is past.
fn expire(said: &mut Said) {
    if said.until.is_some_and(|until| Instant::now() >= until) {
        *said = Said::default();
    }
}

/// `text` with the newest sign-in's code and email taken out, for what the
/// thread keeps: the second route's history, the thread's file and the
/// memory's journal (the first builder at 09:46 on #1676). The words were
/// read from the tool's result or the news as they were said; a later turn
/// is told only that a code was given, so it can't say it again. The code
/// is found however its digits were spaced ("1 2 3 4, 5 6 7 8",
/// "1234-5678"); the email as written or as said.
pub fn scrub(text: &str) -> String {
    let Ok(mut said) = SAID.lock() else {
        return text.to_owned();
    };
    expire(&mut said);
    let mut text = text.to_owned();
    if let Some(code) = said.code.as_deref() {
        text = without_code(&text, code);
    }
    if let Some(email) = said.email.as_deref() {
        for form in [email.to_owned(), spoken_email(email)] {
            text = replace_ignoring_case(&text, &form, "their account");
        }
    }
    text
}

/// `text` with each run of `code`'s digits, in order, with only spaces,
/// commas, dots or dashes between them, said as "a sign-in code".
fn without_code(text: &str, code: &str) -> String {
    let digits: Vec<char> = code.chars().collect();
    let chars: Vec<char> = text.chars().collect();
    let mut kept = String::new();
    let mut at = 0;
    while at < chars.len() {
        let mut next = at;
        let mut matched = 0;
        while matched < digits.len() && next < chars.len() {
            if chars[next] == digits[matched] {
                matched += 1;
                next += 1;
            } else if matched > 0 && matches!(chars[next], ' ' | ',' | '.' | '-') {
                next += 1;
            } else {
                break;
            }
        }
        if !digits.is_empty() && matched == digits.len() {
            kept.push_str("a sign-in code");
            at = next;
        } else {
            kept.push(chars[at]);
            at += 1;
        }
    }
    kept
}

fn replace_ignoring_case(text: &str, find: &str, with: &str) -> String {
    if find.is_empty() {
        return text.to_owned();
    }
    let lower = text.to_lowercase();
    let find = find.to_lowercase();
    // Lowercasing that changes lengths (rare letters) is left as it is.
    if lower.len() != text.len() {
        return text.to_owned();
    }
    let mut kept = String::new();
    let mut from = 0;
    while let Some(found) = lower[from..].find(&find) {
        kept.push_str(&text[from..from + found]);
        kept.push_str(with);
        from += found + find.len();
    }
    kept.push_str(&text[from..]);
    kept
}

pub fn is_tool(name: &str) -> bool {
    name == START || name == ANSWER
}

/// The two functions, declared with the switch.
pub fn tools() -> Vec<Tool> {
    vec![
        Tool {
            name: START.into(),
            description: "Sign this lamp in to the person's Harness, so it can hand work to \
                          their own computer. Call it only when the person asks to sign the lamp \
                          in, or to set up hand-overs to their computer. It gives a code to say \
                          and where they type it. If they ask for the code again, call it again: \
                          while the sign-in is open it gives back the same code. Never say a \
                          sign-in code's digits from memory."
                .into(),
            parameters: None,
            silent: false,
        },
        Tool {
            name: ANSWER.into(),
            description: "The person's answer when you asked whether to sign the lamp in as an \
                          email address: yes only when they clearly said yes to that question, \
                          otherwise no."
                .into(),
            parameters: Some(json!({
                "type": "object",
                "properties": {
                    "answer": {"type": "string", "enum": ["yes", "no"]}
                },
                "required": ["answer"]
            })),
            silent: false,
        },
    ]
}

/// The code's digits as said: one by one, in two groups ("1 2 3 4, 5 6 7
/// 8").
pub fn code_to_say(code: &str) -> String {
    let digits: Vec<String> = code.chars().map(String::from).collect();
    let half = digits.len().div_ceil(2);
    if digits.len() < 6 {
        return digits.join(" ");
    }
    format!("{}, {}", digits[..half].join(" "), digits[half..].join(" "))
}

/// An email as it is read back, slowly and clearly, as Harness asks:
/// "someone at example dot com"; a dash, an underscore and a plus said.
pub fn spoken_email(email: &str) -> String {
    let mut said = String::new();
    for c in email.chars() {
        let word = match c {
            '@' => " at ",
            '.' => " dot ",
            '-' => " dash ",
            '_' => " underscore ",
            '+' => " plus ",
            _ => {
                said.push(c);
                continue;
            }
        };
        said.push_str(word);
    }
    said.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// Where the code is typed, for the model to say.
const WHERE: &str = "they type it into Harness on their computer: in the Harness app under \
                     Machines, Approve a device, or at harness dot autonomous dot ai";

/// What the model is told of a sign-in in this state (the tasks part's
/// `sign_in_state`), as the answer to [`START`].
fn told(state: &Value) -> Value {
    match state["sign_in"].as_str() {
        Some("code") => {
            let code = state["code"].as_str().unwrap_or_default();
            json!({
                "code_to_say": code_to_say(code),
                "next": format!(
                    "Say the code digit by digit, slowly, in the two groups given, then that \
                     {WHERE}. Then say you will ask them to confirm their email once they have \
                     approved it. Never write the code down any other way."
                ),
            })
        }
        Some("starting") => json!({
            "next": "Harness is getting a code. Say briefly that you will read it out in a moment."
        }),
        Some("asking") | Some("answered") => json!({
            "next": "A sign-in is already waiting for the person's answer. Say so in a few words."
        }),
        Some("done") => done_told(state),
        _ => json!({"error": "The sign-in could not be started just now."}),
    }
}

/// How a done sign-in is told.
fn done_told(state: &Value) -> Value {
    if state["result"] == "success" {
        return json!({"result": "The lamp is signed in to Harness. Say so in a few words."});
    }
    let why = match state["code"].as_str().unwrap_or_default() {
        "DENIED" => "it was not approved",
        "EXPIRED" => "the code ran out of time; they can ask again",
        "CANCELLED" => "it was cancelled",
        "harness_too_old" => "Harness on this lamp needs updating first",
        "no_harness" => "Harness is not installed on this lamp",
        "timeout" => "it took too long; they can ask again",
        "too_late" => "the question went unanswered for two minutes; they can ask again",
        _ => "Harness could not sign it in just now",
    };
    json!({"error": format!("The lamp was not signed in: {why}.")})
}

fn ask(socket: &Path, line: &Value, deadline: Duration) -> Option<Value> {
    if deadline.is_zero() {
        return None;
    }
    crate::tools::exchange_up_to(
        socket,
        line,
        deadline.min(ASK_DEADLINE),
        crate::tools::MAX_TASKS_ANSWER_BYTES,
    )
}

fn needs_tasks_update() -> Value {
    json!({"error": "Voice sign-in needs the Tasks update to finish; please try again after it updates."})
}

fn start_refused(answer: &Value) -> Value {
    if answer["error"] == "bad_request" {
        return needs_tasks_update();
    }
    let why = match answer["error"].as_str() {
        Some("sign_in_off" | "untrusted") => "Signing in by voice is not set up on this lamp.",
        Some("timeout" | "busy") => {
            "The lamp's hand-over part is busy just now. Say to ask again in a moment."
        }
        _ => "The sign-in could not be started just now. Say to ask again later.",
    };
    json!({"error": why})
}

/// The owner's remaining lifetime starts before the RPC, so transit cannot
/// extend it. An expired or malformed grant is consumed but never spoken.
fn code_until(state: &Value, started: Instant) -> Option<Instant> {
    let code = state["code"].as_str()?;
    if state["sign_in"] != "code"
        || !(4..=12).contains(&code.len())
        || !code.bytes().all(|b| b.is_ascii_digit())
    {
        return None;
    }
    let until = started.checked_add(Duration::from_secs(state["expires_in"].as_u64()?))?;
    (until > Instant::now()).then_some(until)
}

/// One of the two functions, in the voice's `request`, within `deadline`.
/// Only a request the lamp heard may start or answer a sign-in.
pub fn run(
    directory: &Path,
    call: &ToolCall,
    request: u64,
    heard: bool,
    deadline: Duration,
) -> (Value, bool) {
    if !heard {
        return (
            json!({"error": "Only someone speaking to the lamp may sign it in."}),
            true,
        );
    }
    let started = Instant::now();
    let left = || deadline.saturating_sub(started.elapsed());
    let socket = directory.join("voice.sock");
    let refused = |answer: &Value| answer["ok"] != true;
    match call.name.as_str() {
        START => {
            let Some(capability) = ask(&socket, &json!({"op": "sign_in_state"}), left()) else {
                return (crate::tools::unavailable(), false);
            };
            if refused(&capability) {
                return (start_refused(&capability), true);
            }
            if capability["code_claims"] != 1 {
                return (needs_tasks_update(), true);
            }
            // A heard request is a new START, including an explicit repeat.
            // Its continuation is a claim for this id, never another START.
            let start_sent = Instant::now();
            let Some(mut state) = ask(&socket, &json!({"op": "sign_in_start"}), left()) else {
                return (crate::tools::unavailable(), false);
            };
            if refused(&state) {
                return (start_refused(&state), true);
            }
            if state["sign_in"] == "code" && code_until(&state, start_sent).is_none() {
                return (
                    json!({"error": "That sign-in code is no longer available. Say they can ask to sign in again."}),
                    true,
                );
            }
            let id = state["id"].as_u64();
            while state["sign_in"] == "starting" && left() > LOOK_EVERY + ASK_DEADLINE {
                let Some(id) = id else {
                    return (crate::tools::unavailable(), false);
                };
                std::thread::sleep(LOOK_EVERY);
                let claim_started = Instant::now();
                let Some(read) = ask(
                    &socket,
                    &json!({"op": "sign_in_take_code", "id": id}),
                    left(),
                ) else {
                    return (crate::tools::unavailable(), false);
                };
                if refused(&read) {
                    return (start_refused(&read), true);
                }
                match read["claim"].as_str() {
                    Some("waiting") => {}
                    Some("granted")
                        if read["id"] == id && code_until(&read, claim_started).is_some() =>
                    {
                        state = read;
                    }
                    Some("already_given") => {
                        return (
                            json!({
                                "next": "The sign-in code is already being provided. Do not say it again."
                            }),
                            true,
                        );
                    }
                    Some("not_available" | "granted") => {
                        return (
                            json!({
                                "error": "That sign-in code is no longer available. Say they can ask to sign in again."
                            }),
                            true,
                        );
                    }
                    _ => return (needs_tasks_update(), true),
                }
            }
            if let Some(code) = state["code"].as_str() {
                keep_said(Some(code), None);
                // The lamp says it in this request's answer.
                mark(request);
            }
            (told(&state), true)
        }
        ANSWER => {
            let yes = match call.args.get("answer").and_then(Value::as_str) {
                Some("yes") => true,
                Some("no") => false,
                _ => return (json!({"error": "Give the answer as yes or no."}), true),
            };
            // The lamp's answer may read the account back.
            mark(request);
            // Taken by the tasks part only after the question was heard, in
            // a later request, within two minutes, once.
            let line = json!({
                "op": "sign_in_answer",
                "answer": if yes { "yes" } else { "no" },
                "request": request,
            });
            let Some(answer) = ask(&socket, &line, left()) else {
                return (crate::tools::unavailable(), false);
            };
            if refused(&answer) {
                let why = match answer["error"].as_str() {
                    Some("too_late") => {
                        "The sign-in question was asked too long ago, so the sign-in ended. \
                         Say they can ask to sign in again."
                    }
                    _ => "No sign-in question is waiting for an answer now.",
                };
                return (json!({"error": why}), true);
            }
            (
                json!({"result": if yes {
                    "Passed on. Say you are signing in, and that you will say when it is done."
                } else {
                    "Not signed in. Say so in a few words."
                }}),
                true,
            )
        }
        _ => (crate::tools::unavailable(), false),
    }
}

/// The note that asks the person, unasked, once they approved in Harness.
fn asking_note(email: &str) -> String {
    let said = spoken_email(email);
    format!(
        "Harness on the person's computer was approved for this lamp, and asks to sign it in as \
         {said}. Ask them once, briefly and clearly, reading the address slowly: \"Shall I sign \
         in as {said}?\" Then, on their answer, call {ANSWER}: yes only for a clear yes."
    )
}

/// What the news thread knows of the sign-ins it has seen: the first state
/// each id was seen in, and whether its answer was a no.
#[derive(Debug, Default)]
pub struct Follow {
    seen: std::collections::BTreeMap<u64, Seen>,
}

#[derive(Debug, Default)]
struct Seen {
    /// Seen first already done: the start's own answer told it.
    done_first: bool,
    said_no: bool,
}

/// The key of the sign-in `id`'s news `what`. It has no `:`, so it is never
/// taken for a task's, and neither the code nor the email.
fn key(id: u64, what: &str) -> String {
    format!("sign-in-{id}-{what}")
}

/// Whether `key` is a sign-in's news ([`key`]), not a task's.
pub fn is_news(key: &str) -> bool {
    key.starts_with("sign-in-")
}

/// The sign-in whose question `key` is, if it is one.
pub fn asked_of(key: &str) -> Option<u64> {
    key.strip_prefix("sign-in-")?
        .strip_suffix("-asking")?
        .parse()
        .ok()
}

/// A sign-in note and the code's conservative lifetime, if it is a code.
#[derive(Debug, PartialEq)]
pub struct SignInNews {
    pub key: String,
    pub note: String,
    pub until: Option<Instant>,
}

/// The news of a sign-in (read by the news thread, [`crate::task_news`]),
/// from the tasks part: a code claimed after the start's
/// answer said one, the question once approved in Harness, and how it
/// ended. Each is told once (`offered`). A sign-in first seen done gets no
/// news, since the start's answer told it; nor does one ended after the
/// person said no. Also whether one is open, to be read again soon.
pub fn news(
    directory: &Path,
    offered: &std::collections::BTreeSet<String>,
    follow: &mut Follow,
) -> (Vec<SignInNews>, bool) {
    let started = Instant::now();
    let socket = directory.join("voice.sock");
    let Some(state) = ask(&socket, &json!({"op": "sign_in_state"}), ASK_DEADLINE)
        .filter(|state| state["ok"] == true)
    else {
        return (Vec::new(), false);
    };
    let Some(id) = state["id"].as_u64() else {
        return (Vec::new(), false);
    };
    let what = state["sign_in"].as_str().unwrap_or_default();
    // Only the newest is kept: the tasks part has no other.
    follow.seen.retain(|kept, _| *kept == id);
    let seen = follow.seen.entry(id).or_insert_with(|| Seen {
        done_first: what == "done",
        said_no: false,
    });
    let mut news = Vec::new();
    match what {
        "code" if state["code_told"] != true && !offered.contains(&key(id, "code")) => {
            // State is observational. Both processes claim from the same
            // Tasks owner; neither may speak digits from this older snapshot.
            if state["code_claims"] == 1 {
                let claim_started = Instant::now();
                if let Some(claim) = ask(
                    &socket,
                    &json!({"op": "sign_in_take_code", "id": id}),
                    ASK_DEADLINE.saturating_sub(started.elapsed()),
                )
                .filter(|claim| {
                    claim["ok"] == true && claim["claim"] == "granted" && claim["id"] == id
                }) && let Some(until) = code_until(&claim, claim_started)
                {
                    let code = claim["code"].as_str().unwrap();
                    keep_said(Some(code), None);
                    news.push(SignInNews {
                        key: key(id, "code"),
                        note: format!(
                            "The code to sign this lamp in to Harness is ready: {}. Say it digit by \
                             digit, slowly, in the two groups given, then that {WHERE}.",
                            code_to_say(code)
                        ),
                        until: Some(until),
                    });
                }
            }
        }
        "asking" => {
            keep_said(None, state["email"].as_str());
            if let Some(email) = state["email"].as_str()
                && !offered.contains(&key(id, "asking"))
            {
                news.push(SignInNews {
                    key: key(id, "asking"),
                    note: asking_note(email),
                    until: None,
                });
            }
        }
        "answered" => seen.said_no = state["answer"] == "no",
        "done" if !seen.done_first && !seen.said_no && !offered.contains(&key(id, "done")) => {
            let told = done_told(&state);
            let note = told["result"]
                .as_str()
                .or_else(|| told["error"].as_str())
                .unwrap_or_default()
                .to_owned();
            news.push(SignInNews {
                key: key(id, "done"),
                note,
                until: None,
            });
        }
        _ => {}
    }
    // Tagged, so the worker that says it marks its request ([`written`]).
    let news = news
        .into_iter()
        .map(|mut news| {
            news.note = format!("{NEWS_TAG}{}", news.note);
            news
        })
        .collect();
    (
        news,
        matches!(what, "starting" | "code" | "asking" | "answered"),
    )
}

/// Tell the tasks part that sign-in `id`'s question was heard whole in the
/// voice's `request`: from then its answer is taken. Whether it was taken.
pub fn tell_asked(directory: &Path, id: u64, request: u64) -> bool {
    ask(
        &directory.join("voice.sock"),
        &json!({"op": "sign_in_asked", "id": id, "request": request}),
        ASK_DEADLINE,
    )
    .is_some_and(|answer| answer["ok"] == true)
}

/// What the lamp's words in a request that said a sign-in's code or
/// account leave the worker as, in place of them (#2137's redesign, step 3;
/// the reviewer's P2 and Jarvis's P1). The audio is untouched.
pub const SAID_LINE: &str = "(a sign-in code and account were said)";
/// How each sign-in news note begins: the worker given it marks its
/// request ([`written`]).
pub const NEWS_TAG: &str = "(Sign-in news, for you alone.) ";
/// The most requests kept marked: a sign-in has a few at most.
const MOST_MARKED: usize = 16;

/// In this worker: the tasks part's folder, when signing in by voice is on
/// ([`crate::agent_tasks::SIGN_IN_FLAG`]).
static DIRECTORY: Mutex<Option<PathBuf>> = Mutex::new(None);

/// What the lamp's words in a request of a Live session that heard a
/// sign-in's code or account leave the worker as: the session may say them
/// again in any later request (Jarvis's and the reviewer's P2 on #2137).
pub const HELD_LINE: &str = "(words kept back: this conversation heard a sign-in code)";

/// In this worker: the requests that said a code or an account, those of
/// them marked only for their Live session ([`leaving_live`]), and the ones
/// whose line has left already.
#[derive(Default)]
struct Marked {
    requests: BTreeSet<u64>,
    held: BTreeSet<u64>,
    lined: BTreeSet<u64>,
}
static MARKED: Mutex<Marked> = Mutex::new(Marked {
    requests: BTreeSet::new(),
    held: BTreeSet::new(),
    lined: BTreeSet::new(),
});

std::thread_local! {
    /// The Live session that heard a code or an account. The Live worker
    /// runs on one thread (its current-thread runtime), which sees both
    /// its connections and its words, so it is kept there: each test's
    /// worker has its own.
    static HELD_SESSION: std::cell::Cell<Option<u64>> = const { std::cell::Cell::new(None) };
}

impl Marked {
    fn mark(&mut self, request: u64) {
        self.requests.insert(request);
        while self.requests.len() > MOST_MARKED {
            self.requests.pop_first();
        }
        let Self {
            requests,
            held,
            lined,
            ..
        } = self;
        held.retain(|kept| requests.contains(kept));
        lined.retain(|kept| requests.contains(kept));
    }
}

/// Signing in by voice is on in this worker, with the tasks part in
/// `directory`.
pub fn serve_from(directory: &Path) {
    if let Ok(mut kept) = DIRECTORY.lock() {
        *kept = Some(directory.to_path_buf());
    }
}

/// The lamp's words in `request` say a code or an account: they leave this
/// worker as [`SAID_LINE`].
pub fn mark(request: u64) {
    if let Ok(mut marked) = MARKED.lock() {
        marked.mark(request);
    }
}

pub fn marked(request: u64) -> bool {
    MARKED
        .lock()
        .is_ok_and(|marked| marked.requests.contains(&request))
}

/// A written request this worker was given (the coordinator's news): one
/// that is a sign-in's is marked, and the code and the account are read
/// from the tasks part, so that what is kept of the note and of the
/// person's words can leave them out ([`scrub`], [`scrub_piece`]); once it
/// ended, they are kept [`KEPT_AFTER`] more. The read is off the worker's
/// loop, so a slow tasks part never holds its sound (the reviewer's P3 4
/// on #2137); its request's own words are its line whatever it finds.
pub fn written(request: u64, text: &str) -> Option<std::thread::JoinHandle<()>> {
    if !text.starts_with(NEWS_TAG) {
        return None;
    }
    mark(request);
    let directory = DIRECTORY.lock().ok().and_then(|kept| kept.clone())?;
    std::thread::Builder::new()
        .name("sign-in-said".into())
        .spawn(move || {
            let Some(state) = ask(
                &directory.join("voice.sock"),
                &json!({"op": "sign_in_state"}),
                ASK_DEADLINE,
            ) else {
                return;
            };
            keep_said(state["code"].as_str(), state["email"].as_str());
            if state["sign_in"] == "done" {
                said_ended();
            }
        })
        .ok()
}

/// What leaves this worker of `output`: the lamp's words in a marked
/// request as [`SAID_LINE`], once, its later pieces empty; the person's
/// words with the code and the account taken out, piece by piece. Called
/// again on what it gave, it gives the same.
pub fn leaving(output: &mut crate::provider_worker::ProviderOutput) {
    if let crate::provider_worker::ProviderOutput::Transcript { request, text, .. } = output {
        *text = leaving_text(*request, std::mem::take(text));
    }
}

/// [`leaving`] for words of `request` (none: the person's), as they come
/// from the service, before anything keeps them.
pub fn leaving_text(request: Option<u64>, text: String) -> String {
    let Some(request) = request else {
        return scrub_piece(&text);
    };
    let Ok(mut marked) = MARKED.lock() else {
        return text;
    };
    if text == SAID_LINE || text == HELD_LINE || text.is_empty() {
        return text;
    }
    // Not marked: the model may still say the code or the account from
    // what it guesses or recalls ("Three one five eight three" on
    // lamp-75c9, 21 Oct, asked for the code again in a request of its
    // own): taken out as from the person's words (#2602 finding 5).
    if !marked.requests.contains(&request) {
        return scrub_piece(&text);
    }
    if !marked.lined.insert(request) {
        String::new()
    } else if marked.held.contains(&request) {
        HELD_LINE.to_owned()
    } else {
        SAID_LINE.to_owned()
    }
}

/// A marked `request` was heard in Live session `session`, with words or
/// none (an answer cut before its first word, the asking note): that
/// session heard the code or the account.
pub fn in_session(request: u64, session: u64) {
    if marked(request) {
        HELD_SESSION.set(Some(session));
    }
}

/// A Live connection was made as `session`: `resumed`, it goes on with the
/// conversation before it, so what that one heard is held in it too; fresh,
/// it heard nothing, and nothing is held.
pub fn connected(session: u64, resumed: bool) {
    HELD_SESSION.set(if resumed {
        HELD_SESSION.get().map(|_| session)
    } else {
        None
    });
}

/// [`leaving_text`] for the lamp's words of `request` in Live session
/// `session`: once a marked request's words come in a session, that
/// session heard the code or the account, and may say them again in any
/// later request, so each of its requests leaves as [`HELD_LINE`], in it
/// and in any connection resumed from it ([`connected`]), until a fresh
/// one (Jarvis's and the reviewer's P2 on #2137). The audio is untouched.
pub fn leaving_live(request: u64, session: u64, text: String) -> String {
    if let Ok(mut marked) = MARKED.lock() {
        if marked.requests.contains(&request) {
            HELD_SESSION.set(Some(session));
        } else if HELD_SESSION.get() == Some(session) {
            marked.mark(request);
            marked.held.insert(request);
        }
    }
    leaving_text(Some(request), text)
}

/// In this worker: the person's words of the line being heard, held while
/// a sign-in's code or account is kept ([`person_piece`]).
static PERSON: Mutex<String> = Mutex::new(String::new());
/// The most of a line held: past it, what is held leaves.
const MOST_HELD: usize = 4_000;

/// The person's words on Live as they leave this worker. While a sign-in's
/// code or account is kept, each piece is held until its line is finished,
/// and the line leaves whole, scrubbed: a piece split inside the code or
/// the account can't be scrubbed alone, and one sent can't be taken back
/// (Jarvis's P2 on #2137). Empty for a piece held. Otherwise each piece is
/// scrubbed as it comes ([`scrub_piece`]). The second route hears each line
/// whole, so it never needs this.
pub fn person_piece(text: &str, finished: bool) -> String {
    let holding = SAID.lock().is_ok_and(|mut said| {
        expire(&mut said);
        said.code.is_some() || said.email.is_some()
    });
    let Ok(mut held) = PERSON.lock() else {
        return scrub_piece(text);
    };
    if !holding && held.is_empty() {
        return scrub_piece(text);
    }
    held.push_str(text);
    if finished || !holding || held.len() > MOST_HELD {
        let whole = std::mem::take(&mut *held);
        return scrub_piece(&whole);
    }
    String::new()
}

/// [`scrub`], and for a piece of the person's words, also any run of three
/// or more of the code's digits in its order, and the account's name or its
/// domain on its own, as written or as said (Jarvis's P2: the words come
/// in pieces split anywhere).
pub fn scrub_piece(text: &str) -> String {
    let mut text = scrub(text);
    let Ok(mut said) = SAID.lock() else {
        return text;
    };
    expire(&mut said);
    if let Some(code) = said.code.as_deref() {
        text = without_code_part(&text, code);
        text = without_code_words(&text, code);
    }
    if let Some((name, domain)) = said
        .email
        .as_deref()
        .and_then(|email| email.split_once('@'))
    {
        for part in [name, domain] {
            for form in [part.to_owned(), spoken_email(part)] {
                if form.chars().filter(char::is_ascii_alphanumeric).count() >= 3 {
                    text = replace_ignoring_case(&text, &form, "their account");
                }
            }
        }
    }
    text
}

/// The digit a word says, if it says one ("four", "oh").
fn digit_word(word: &str) -> Option<char> {
    let word: String = word
        .chars()
        .filter(|c| c.is_alphanumeric())
        .collect::<String>()
        .to_lowercase();
    Some(match word.as_str() {
        "zero" | "oh" => '0',
        "one" => '1',
        "two" => '2',
        "three" => '3',
        "four" => '4',
        "five" => '5',
        "six" => '6',
        "seven" => '7',
        "eight" => '8',
        "nine" => '9',
        _ => return None,
    })
}

/// `text` with each run of three or more digits said as words ("four eight
/// two"), a part of `code` in its order, said as "a sign-in code" (Jarvis's
/// test 3).
fn without_code_words(text: &str, code: &str) -> String {
    let words: Vec<&str> = text.split_inclusive(char::is_whitespace).collect();
    let mut kept = String::new();
    let mut at = 0;
    while at < words.len() {
        let mut end = at;
        let mut digits = String::new();
        while let Some(digit) = words.get(end).and_then(|word| digit_word(word)) {
            digits.push(digit);
            end += 1;
        }
        if digits.len() >= 3 && code.contains(&digits) {
            kept.push_str("a sign-in code");
            // The spacing and stop after the last word are kept.
            let last = words[end - 1];
            kept.extend(last.chars().filter(|c| !c.is_alphanumeric()));
            at = end;
        } else {
            kept.push_str(words[at]);
            at += 1;
        }
    }
    kept
}

/// `text` with each run of three or more digits that is a part of `code`,
/// in its order, spaced as [`without_code`] allows, said as "a sign-in
/// code".
fn without_code_part(text: &str, code: &str) -> String {
    let chars: Vec<char> = text.chars().collect();
    let mut kept = String::new();
    let mut at = 0;
    while at < chars.len() {
        // The run of digits from here, with only spacing between them.
        let mut digits = String::new();
        let mut next = at;
        let mut end = at;
        while next < chars.len() {
            if chars[next].is_ascii_digit() {
                digits.push(chars[next]);
                next += 1;
                end = next;
            } else if !digits.is_empty() && matches!(chars[next], ' ' | ',' | '.' | '-') {
                next += 1;
            } else {
                break;
            }
        }
        if digits.len() >= 3 && code.contains(&digits) {
            kept.push_str("a sign-in code");
            at = end;
        } else if digits.is_empty() {
            kept.push(chars[at]);
            at += 1;
        } else {
            kept.extend(&chars[at..end]);
            at = end;
        }
    }
    kept
}

/// The code and the account, as a sign-in's would be kept, for a test of
/// a worker's path.
#[cfg(test)]
pub(crate) fn keep_said_for_test(code: &str, email: &str) {
    keep_said(Some(code), Some(email));
}

#[cfg(test)]
pub(crate) fn forget() {
    if let Ok(mut marked) = MARKED.lock() {
        *marked = Marked::default();
    }
    if let Ok(mut said) = SAID.lock() {
        *said = Said::default();
    }
    if let Ok(mut held) = PERSON.lock() {
        held.clear();
    }
    HELD_SESSION.set(None);
}

/// The Live session that heard a sign-in's code, for a test of a resumed
/// connection.
#[cfg(test)]
pub(crate) fn held_session_for_test() -> Option<u64> {
    HELD_SESSION.get()
}

/// The sign-in ended `ago` already, for a test of how long its code and
/// account are kept.
#[cfg(test)]
pub(crate) fn ended_for_test(ago: Duration) {
    said_ended();
    if let Ok(mut said) = SAID.lock() {
        said.until = said.until.and_then(|until| until.checked_sub(ago));
    }
}

