        let cases = [
            (
                vec![json!({"ok":true,"sign_in":"none"})],
                vec!["sign_in_state"],
                "Tasks update",
                false,
            ),
            (
                vec![capable.clone(), json!({"ok":false,"error":"bad_request"})],
                vec!["sign_in_state", "sign_in_start"],
